const item = $input.first().json;
const headers = item.headers ?? {};
const provided = String(headers['x-n8n-secret'] ?? headers['X-N8N-Secret'] ?? '');
const expected = String($env.N8N_WEBHOOK_SECRET ?? '');
if (!expected) throw new Error('N8N_WEBHOOK_SECRET is not configured in n8n');
if (provided.length !== expected.length) throw new Error('Unauthorized: bad webhook secret');
let diff = 0;
for (let i = 0; i < expected.length; i++) diff |= provided.charCodeAt(i) ^ expected.charCodeAt(i);
if (diff !== 0) throw new Error('Unauthorized: bad webhook secret');
return [$input.first()];

const j = $input.first().json;
const code = Number(j.statusCode ?? 0);
const reachable = code >= 200 && code < 400;
// product travels from the webhook item (http node replaced item data)
const wh = $('webhook-entry').first().json;
const product = (wh.body ?? wh).product ?? {};
return [{ json: { product, reachable, statusCode: code,
  error: j.error ?? null } }];

const p = $json.product;
return [{ json: { product: { ...p, affiliateValid: True,
  affiliateCheckedAt: new Date().toISOString() } } }];

const p = $json.product;
console.log('[affiliate-check] broken link', $json.statusCode, $json.error);
return [{ json: { product: { ...p, state: 'NEEDS_REVIEW', affiliateValid: False },
  reason: 'broken_affiliate_link' } }];
